import { CONFIG, money, number, dateLabel, dateTimeLabel, periodLabel, daysInPeriod, isoDate, prevPeriod, today } from "./config.js";
import { Store, providerAvailableInBranch, sourceIdentity } from "./store.js";

export const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const rows = (name, period, branch) => Store.list(name, period, branch);
const kpi = (label, value, hint="", cls="") => `<article class="kpi ${cls}"><span>${esc(label)}</span><strong>${value}</strong><small>${esc(hint)}</small></article>`;
const table = (headers, body, empty="No hay registros para mostrar.") => {
 const hasSelection=String(body||'').includes('data-bulk-select=');
 const collection=(String(body||'').match(/data-bulk-select="([^"]+)"/)||[])[1]||'';
 const head=hasSelection?['<input type="checkbox" title="Seleccionar todo" data-bulk-select-all="'+esc(collection)+'">',...headers]:headers;
 const toolbar=hasSelection?`<div class="bulk-toolbar"><span>Seleccioná movimientos para operar en conjunto.</span><button class="danger-button" data-bulk-delete="${esc(collection)}">Enviar seleccionados a papelera</button></div>`:'';
 return `${toolbar}<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${body || `<tr><td colspan="${head.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`;
};
const actions = (collection,id,editType=collection) => {
 const readOnly = typeof window !== "undefined" && window.__blunnoBranch === "General" && ["invoices","cash","expenses","investments","employees","hours","incomes"].includes(collection);
 if (readOnly) return `<div class="row-actions"><button class="secondary-button compact-button" data-detail="${esc(collection)}" data-id="${esc(id)}">Ver</button></div>`;
 const editButton=collection==='invoices'?`<button type="button" data-invoice-edit="${esc(id)}">Editar</button>`:`<button type="button" data-edit="${editType}" data-id="${esc(id)}">Editar</button>`;
 return `<div class="row-actions"><input type="checkbox" aria-label="Seleccionar" data-bulk-select="${esc(collection)}" data-id="${esc(id)}">${editButton}<button type="button" class="danger-link" data-delete="${esc(collection)}" data-id="${esc(id)}">Eliminar</button></div>`;
};
const branchFilter = branch => CONFIG.profiles.map(x=>`<button class="filter-chip ${x===branch?'active':''}" data-profile="${x}">${x}</button>`).join("");

export const formSchema = {
  cash: [
    ["date","Fecha","date"],["branch","Sucursal","select",CONFIG.branches],
    ["type","Tipo","select",[["income","Ingreso"],["expense","Gasto de caja"],["payment","Pago"]]],
    ["concept","Concepto","text"],["amount","Importe","number"],["expected","Importe esperado","number"],
    ["notes","Observaciones","textarea"],["lateMovement","Movimiento tardío","checkbox"]
  ],
  provider: [["name","Proveedor","text"]],
  invoice: [
    ["provider","Proveedor","text"],["number","N° de factura","text"],["operationDate","Fecha del movimiento","date"],
    ["loadDate","Fecha de carga","date"],["branch","Sucursal","select",CONFIG.branches],
    ["amount","Importe","number"],["notes","Observaciones","textarea"],["lateMovement","Carga tardía de período cerrado","checkbox"]
  ],
  income: [
    ["date","Fecha","date"],["branch","Sucursal","select",CONFIG.branches],["method","Medio / categoría","select",["Tarjeta","Contado","Mayoristas","Banco","Transferencia","Otros"]],["concept","Origen / concepto","text"],
    ["amount","Importe","number"],["notes","Detalle","textarea"],["lateMovement","Movimiento tardío","checkbox"]
  ],
  expense: [
    ["date","Fecha","date"],["branch","Sucursal","select",CONFIG.branches],["category","Categoría","select",CONFIG.expenseCategories],
    ["concept","Detalle / resumen","text"],["amount","Importe","number"],["document","Comprobante / referencia","text"],["notes","Observaciones","textarea"],
    ["lateMovement","Movimiento tardío","checkbox"]
  ],
  investment: [
    ["date","Fecha","date"],["branch","Sucursal","select",CONFIG.branches],["concept","Resumen de la inversión","text"],
    ["amount","Importe","number"],["document","Comprobante / referencia","text"],["notes","Detalle","textarea"],["lateMovement","Movimiento tardío","checkbox"]
  ],
  employee: [["name","Nombre completo","text"],["branch","Sucursal","select",CONFIG.branches],["role","Puesto","text"],["hourlyRate","Valor hora actual","number"],["active","Estado","select",[["true","Activo"],["false","Inactivo"]]]],
  hours: [["employee","Empleado","text"],["date","Fecha","date"],["hours","Horas","number"],["advance","Adelanto / vale","number"],["merchandise","Mercadería","number"],["holiday","Feriado","select",[["no","No"],["yes","Sí"]]],["notes","Observaciones","textarea"]],
  task: [["title","Tarea / recordatorio","text"],["dueDate","Fecha","date"],["dueTime","Hora","time"],["priority","Prioridad","select",[["normal","Normal"],["high","Alta"],["urgent","Urgente"]]],["responsible","Responsable","select",CONFIG.responsiblePeople],["repeat","Repetición","select",[["none","Sin repetición"],["daily","Diaria"],["weekly","Semanal"],["monthly","Mensual"]]],["notes","Notas","textarea"]]
};

export function renderDashboard(content, period, branch="General") {
  const s=Store.summary(period,branch), prev=Store.summary(prevPeriod(period),branch);
  const pct=(a,b)=>a===0?(b===0?0:100):((b-a)/Math.abs(a))*100;
  const alerts=[];
  if(s.income===0) alerts.push("No hay ingresos independientes cargados para el período seleccionado.");
  const tasks=Store.list("tasks").filter(x=>x.status!=="completed").sort((a,b)=>`${a.dueDate} ${a.dueTime}`.localeCompare(`${b.dueDate} ${b.dueTime}`)).slice(0,4);
  const detailButton=(kind,label,value,hint)=>`<button class="kpi kpi-click" data-dashboard-detail="${kind}"><span>${esc(label)}</span><strong>${value}</strong><small>${esc(hint)}</small></button>`;
  content.innerHTML=`
    <div class="profile-bar"><div><span class="section-kicker">PERFIL DE TRABAJO</span><b>${esc(branch)}</b><small>${branch==='General'?'Vista consolidada: no mezcla ni modifica las sucursales.':'Los valores se filtran exclusivamente a esta sucursal.'}</small></div><div class="profile-chips">${branchFilter(branch)}</div></div>
    <section class="hero"><div><span class="hero-tag">CENTRO DE CONTROL BLUNNO</span><h2>Todo el negocio, ordenado y trazable.</h2><p>${periodLabel(period)} · ${esc(branch)} · cada cambio queda auditado.</p><div class="hero-actions"><button class="primary-button" data-view-jump="close">Preparar cierre</button><button class="secondary-button" data-pdf-close="dashboard">PDF del resumen</button></div></div><img src="distri.jpeg" alt="Distribuidora Blunno"></section>
    <div class="kpi-grid">${detailButton("income","Ingresos",money(s.income),`${Store.list('incomes',period,branch).length} movimientos independientes`)}${detailButton("expenses","Gastos del local",money(s.localExpense),`${s.expenseCount} movimientos`)}${detailButton("providers","Proveedores",money(s.providers),`${s.invoiceCount} facturas cargadas`)}${detailButton("investments","Inversiones",money(s.investment),`${s.investmentCount} movimientos`)}${detailButton("salary","Personal",money(s.salary),`${s.liquidationCount} liquidaciones / horas`)}${detailButton("result","Resultado",money(s.result),"Sin incluir Caja diaria")}</div>
    <div class="grid-2"><section class="panel"><div class="panel-head"><div><span class="section-kicker">VARIACIÓN</span><h3>Contra ${periodLabel(prevPeriod(period))}</h3></div></div>${metricLine("Ingresos",prev.income,s.income,pct(prev.income,s.income))}${metricLine("Gastos del local",prev.localExpense,s.localExpense,pct(prev.localExpense,s.localExpense))}${metricLine("Resultado",prev.result,s.result,pct(prev.result,s.result))}</section><section class="panel"><div class="panel-head"><div><span class="section-kicker">CONTROL</span><h3>Alertas y pendientes</h3></div></div>${alerts.length?alerts.map(a=>`<div class="alert-row warning">⚠ ${esc(a)}</div>`).join(''):'<div class="alert-row success">✓ No hay alertas críticas detectadas.</div>'}${tasks.map(t=>`<div class="task-mini"><b>${esc(t.title)}</b><span>${dateLabel(t.dueDate)} ${esc(t.dueTime||'')} · ${esc(t.responsible)}</span></div>`).join('')}</section></div>
  `;
}

function metricLine(label,a,b,p){return `<div class="metric-line"><div><b>${esc(label)}</b><span>${money(a)} → ${money(b)}</span></div><strong class="${p>=0?'up':'down'}">${p>=0?'+':''}${p.toFixed(1)}%</strong></div>`}

export function renderCash(content,period,branch="General"){
 const cashLateOn=String(period)!==String(today()).slice(0,7) && (()=>{try{return sessionStorage.getItem(`blunno-cash-late-${period}-${branch}`)==='1'}catch{return false}})();
 const data=rows("cash",period,branch);
 const cashIndex=new Map(data.map(x=>[`${x.type}|${x.date}|${x.concept||'Sin concepto'}`,x]));
 const dailyTotals=new Map();
 for(const x of data){const d=String(x.date||'').slice(-2);if(!d)continue;const key=x.date;const t=dailyTotals.get(key)||{inc:0,exp:0,pay:0};if(x.type==='income'&&!/^saldo\s+d[ií]a\s+anterior$/i.test(String(x.concept||'')))t.inc+=Number(x.amount||0);if(x.type==='expense')t.exp+=Number(x.amount||0);if(x.type==='payment')t.pay+=Number(x.amount||0);dailyTotals.set(key,t)}
 const valueFor=(type,date,concept)=>cashIndex.get(`${type}|${date}|${concept}`);
 const days=daysInPeriod(period), weeks=Math.max(1,Math.ceil(days/7));
 const rawIndex=Number(localStorage.getItem(`blunno-cash-week-${period}-${branch}`)||0);
 const weekIndex=Math.min(Math.max(rawIndex,0),weeks-1);
 const startDay=weekIndex*7+1,endDay=Math.min(startDay+6,days),weekDays=Array.from({length:endDay-startDay+1},(_,i)=>startDay+i);
 const opening=getOpeningForView(period,branch);
 const conceptsByType={income:Store.cashConcepts('income',period,branch),expense:Store.cashConcepts('expense',period,branch),payment:Store.cashConcepts('payment',period,branch)};
 const dayTotals=Array.from({length:days},(_,i)=>{const d=i+1,date=isoDate(period,d),t=dailyTotals.get(date)||{inc:0,exp:0,pay:0};return {d,date,inc:t.inc,exp:t.exp,pay:t.pay}});
 let saldo=opening;dayTotals.forEach(x=>{x.opening=saldo;x.available=saldo+x.inc;x.rest=x.available-x.exp-x.pay;saldo=x.rest});
 const kindTitle={income:'Ingresos','expense-payment':'Gastos / Pagos de caja'};
 const carryConcept=c=>/^saldo\s+d[ií]a\s+anterior$/i.test(String(c||''));
 const inputDisabled=(rowType,c)=>branch==='General'||carryConcept(c)||(String(period)!==String(today()).slice(0,7)&&!cashLateOn);
 const deleteConceptButton=(rowType,c)=>branch!=='General'&&!Store.isProtectedCashConcept(rowType,c)?`<button type="button" class="cash-concept-delete" data-cash-delete-concept="${esc(c)}" data-cash-delete-concept-id="${esc(Store.cashConceptId(period,branch,rowType,c))}" data-cash-delete-type="${rowType}">Eliminar</button>`:'';
 let savedDay=0;try{savedDay=Number(sessionStorage.getItem(`blunno-cash-mobile-day-${period}-${branch}`)||0)}catch{}
 const currentDay=String(period)===String(today()).slice(0,7)?Number(String(today()).slice(-2)):0;
 const mobileOpenDay=weekDays.includes(savedDay)?savedDay:(weekDays.includes(currentDay)?currentDay:startDay);
 const matrix=(type)=>{
   const isCombined=type==='expense-payment';
   const rowTypes=isCombined?['expense','payment']:[type];
   const matrixRows=rowTypes.flatMap(rowType=>conceptsByType[rowType].map(name=>({type:rowType,name})));
   const headActions=branch==='General'?'':(isCombined
     ? `<div class="row-actions"><button class="secondary-button" data-cash-add-row="expense">＋ Agregar gasto</button><button class="secondary-button" data-cash-add-row="payment">＋ Agregar pago</button></div>`
     : `<button class="secondary-button" data-cash-add-row="${type}">＋ Agregar concepto</button>`);
   const dailyFooter=(day)=>isCombined
     ? `<span class="cash-footer-split">Gastos: ${money(dayTotals[day-1].exp)}</span><span class="cash-footer-split">Pagos: ${money(dayTotals[day-1].pay)}</span>`
     : money(dayTotals[day-1].inc);
   const grandFooter=isCombined
     ? `<span class="cash-footer-split">Gastos: ${money(weekDays.reduce((sum,d)=>sum+dayTotals[d-1].exp,0))}</span><span class="cash-footer-split">Pagos: ${money(weekDays.reduce((sum,d)=>sum+dayTotals[d-1].pay,0))}</span>`
     : money(weekDays.reduce((sum,d)=>sum+dayTotals[d-1].inc,0));
   const rowsHtml=matrixRows.map(({type:rowType,name:c})=>{
     const carry=carryConcept(c),rowTotal=weekDays.reduce((sum,d)=>sum+Number(valueFor(rowType,isoDate(period,d),c)?.amount||0),0);
     return `<tr><th class="sticky-col"><div class="cash-concept-label"><span>${isCombined?`<small class="cash-type-hint">${rowType==='expense'?'GASTO':'PAGO'}</small>`:''}${esc(c)}</span>${deleteConceptButton(rowType,c)}</div></th>${weekDays.map(d=>{const date=isoDate(period,d),r=valueFor(rowType,date,c),carryValue=dayTotals[d-1]?.opening||0;return `<td data-cash-cell data-type="${rowType}" data-concept="${esc(c)}" data-date="${date}"><input inputmode="decimal" ${inputDisabled(rowType,c)?'disabled':''} value="${carry?esc(carryValue):r?esc(r.amount):''}" placeholder="—" title="${carry?'Calculado automáticamente desde el resto del día anterior':''}"></td>`}).join('')}<td class="total-cell">${carry?'—':money(rowTotal)}</td></tr>`;
   }).join('')||`<tr><td colspan="${weekDays.length+2}" class="empty">No hay conceptos definidos.</td></tr>`;
   const mobileEntries=(rowType,date)=>{
     const names=conceptsByType[rowType].filter(c=>!carryConcept(c));
     if(!names.length)return `<div class="cash-mobile-empty">No hay conceptos definidos.</div>`;
     const rows=names.map(c=>{const r=valueFor(rowType,date,c);return `<tr><th scope="row"><div class="cash-mobile-concept"><span>${esc(c)}</span>${deleteConceptButton(rowType,c)}</div></th><td data-cash-cell data-type="${rowType}" data-concept="${esc(c)}" data-date="${date}"><input inputmode="decimal" autocomplete="off" aria-label="${esc(c)} · ${dateLabel(date)}" ${inputDisabled(rowType,c)?'disabled':''} value="${r?esc(r.amount):''}" placeholder="$ 0"></td></tr>`}).join('');
     return `<table class="cash-mobile-entry-table"><tbody>${rows}</tbody></table>`;
   };
   const mobileGroup=(rowType,date)=>`<section class="cash-mobile-entry-group"><h4>${rowType==='income'?'Ingresos':rowType==='expense'?'Gastos':'Pagos'}</h4>${mobileEntries(rowType,date)}</section>`;
   const mobileDays=weekDays.map(d=>{
     const t=dayTotals[d-1],date=t.date;
     const dayName=new Date(`${date}T12:00:00`).toLocaleDateString('es-AR',{weekday:'long'});
     const amount=isCombined?t.exp+t.pay:t.inc;
     const hint=isCombined?`${conceptsByType.expense.filter(c=>!carryConcept(c)).length} conceptos de gastos · ${conceptsByType.payment.length} pagos`:`${conceptsByType.income.filter(c=>!carryConcept(c)).length} conceptos para cargar`;
     const groups=isCombined?`${mobileGroup('expense',date)}${mobileGroup('payment',date)}`:mobileGroup('income',date);
     return `<details class="cash-mobile-day-card" data-cash-mobile-day="${d}" ${d===mobileOpenDay?'open':''}><summary><span class="cash-mobile-day-title"><b>${esc(dayName)} · ${d}</b><small>${hint}</small></span><span class="cash-mobile-day-total"><small>${isCombined?'Gastos + pagos':'Ingresos'}</small><strong>${money(amount)}</strong></span><span class="cash-mobile-chevron">⌄</span></summary><div class="cash-mobile-day-body">${groups}</div></details>`;
   }).join('');
   return `<section class="panel cash-matrix-panel cash-matrix-${isCombined?'outflows':'income'}"><div class="panel-head"><div><span class="section-kicker">${type==='income'?'INGRESOS':'GASTOS / PAGOS'}</span><h3>${kindTitle[type]}</h3></div>${headActions}</div><div class="sheet-wrap cash-desktop-view"><table class="matrix-table cash-main-matrix"><thead><tr><th class="sticky-col">Concepto</th>${weekDays.map(d=>{const dt=new Date(`${isoDate(period,d)}T12:00:00`);return `<th>${dt.toLocaleDateString('es-AR',{weekday:'short'}).replace('.','')}<small>${d}</small></th>`}).join('')}<th>TOTAL</th></tr></thead><tbody>${rowsHtml}</tbody><tfoot><tr><th class="sticky-col">TOTAL</th>${weekDays.map(d=>`<th>${dailyFooter(d)}</th>`).join('')}<th>${grandFooter}</th></tr></tfoot></table></div><div class="cash-mobile-view cash-mobile-day-list">${mobileDays}</div></section>`;
 };
 const mobileControl=weekDays.map(d=>{const t=dayTotals[d-1],date=t.date,dayName=new Date(`${date}T12:00:00`).toLocaleDateString('es-AR',{weekday:'long'});return `<details class="cash-control-mobile-day" data-cash-mobile-day="${d}" ${d===mobileOpenDay?'open':''}><summary><span><b>${esc(dayName)} · ${d}</b><small>Ver desglose del día</small></span><span class="cash-control-rest"><small>RESTO FINAL</small><strong>${money(t.rest)}</strong></span><span class="cash-mobile-chevron">⌄</span></summary><div class="cash-control-mobile-facts"><div><span>Saldo anterior</span><b>${money(t.opening)}</b></div><div><span>Ingresos</span><b>${money(t.inc)}</b></div><div><span>Plata disponible</span><b>${money(t.available)}</b></div><div><span>Gastos</span><b>${money(t.exp)}</b></div><div><span>Pagos</span><b>${money(t.pay)}</b></div><div class="cash-control-rest-fact"><span>Resto final</span><b>${money(t.rest)}</b></div></div></details>`}).join('');
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">CAJA DIARIA · CUADRO OPERATIVO</span><b>${esc(branch)}</b><small>Control físico de dinero. No alimenta el resultado económico. Semana ${weekIndex+1} de ${weeks} · días ${startDay}–${endDay}.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div>
 <div class="cash-week-nav"><button class="secondary-button" data-cash-week="prev" ${weekIndex===0?'disabled':''}>← Semana anterior</button><strong>Semana ${weekIndex+1} · ${dateLabel(isoDate(period,startDay))} al ${dateLabel(isoDate(period,endDay))}</strong><button class="secondary-button" data-cash-week="next" ${weekIndex===weeks-1?'disabled':''}>Semana siguiente →</button></div>
 ${String(period)!==String(today()).slice(0,7)&&!cashLateOn?`<div class="notice warning cash-late-notice"><b>Edición tardía desactivada.</b> Activá el botón rojo para habilitar correcciones y nuevas cargas de este mes.</div>`:''}
 <div class="cash-topbar"><div><span>Saldo inicial del período</span><strong>${money(opening)}</strong><small>El resto de cada día pasa automáticamente al siguiente.</small></div>${branch!=='General'?`<button id="cashLateEditButton" class="cash-late-edit-button ${cashLateOn?'enabled':'disabled'}" type="button" aria-pressed="${cashLateOn?'true':'false'}" title="${cashLateOn?'Pulsá para desactivar la edición tardía':'Pulsá para activar la edición tardía'}"><span class="cash-late-indicator"></span>${cashLateOn?'DESACTIVAR EDICIÓN TARDÍA':'ACTIVAR EDICIÓN TARDÍA'}</button><button id="cashOpeningButton" class="secondary-button">Editar saldo inicial</button>`:''}<button class="secondary-button" data-pdf-close="cash">Generar PDF</button></div>
 <div class="mini-kpis">${kpi('Ingresos',money(dayTotals.reduce((s,x)=>s+x.inc,0)),'Período')}${kpi('Gastos / Pagos',money(dayTotals.reduce((s,x)=>s+x.exp+x.pay,0)),'Total de egresos de caja')}${kpi('Resto final',money(saldo),'Saldo que arranca el siguiente día')}</div>
 ${matrix('income')}${matrix('expense-payment')}
 <section class="panel cash-control-panel"><div class="panel-head"><div><span class="section-kicker">CONTROL DIARIO</span><h3>Saldo anterior + ingresos − gastos − pagos = resto</h3></div></div><div class="table-wrap cash-control-desktop"><table class="matrix-table"><thead><tr><th>Día</th>${weekDays.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody><tr><th>SALDO ANTERIOR</th>${weekDays.map(d=>`<td>${money(dayTotals[d-1].opening)}</td>`).join('')}</tr><tr><th>INGRESOS</th>${weekDays.map(d=>`<td>${money(dayTotals[d-1].inc)}</td>`).join('')}</tr><tr><th>PLATA DISPONIBLE</th>${weekDays.map(d=>`<td>${money(dayTotals[d-1].available)}</td>`).join('')}</tr><tr><th>GASTOS</th>${weekDays.map(d=>`<td>${money(dayTotals[d-1].exp)}</td>`).join('')}</tr><tr><th>PAGOS</th>${weekDays.map(d=>`<td>${money(dayTotals[d-1].pay)}</td>`).join('')}</tr><tr class="total-row"><th>RESTO</th>${weekDays.map(d=>`<td>${money(dayTotals[d-1].rest)}</td>`).join('')}</tr></tbody></table></div><div class="cash-control-mobile-grid">${mobileControl}</div></section>`;
}
function getOpeningForView(period,branch){return Number(Store.db.settings.find(x=>x.id===`cash-opening-${period}-${branch}`)?.amount||0)}

export function renderIncome(content,period,branch="General"){ const data=rows('incomes',period,branch).sort((a,b)=>String(b.date).localeCompare(String(a.date))); const total=data.reduce((s,x)=>s+Number(x.amount||0),0); content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">INGRESOS</span><b>${esc(branch)}</b><small>Ingresos del negocio separados de Caja diaria.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><div class="page-intro"><div><h2>Ingresos</h2><p>Estos importes son los que alimentan el indicador Ingresos de la página principal. Caja diaria queda completamente separada.</p></div><button class="secondary-button" data-pdf-close="income">PDF</button><button class="primary-button" data-new="income">＋ Nuevo ingreso</button></div><div class="mini-kpis">${kpi('Total',money(total))}${kpi('Movimientos',data.length)}</div>${table(['Fecha','Medio','Concepto','Sucursal','Importe','Acciones'],data.map(x=>`<tr><td>${dateLabel(x.date)}</td><td>${esc(x.method||'—')}</td><td><b>${esc(x.concept||'Sin concepto')}</b></td><td>${esc(x.branch)}</td><td>${money(x.amount)}</td><td>${actions('incomes',x.id,'income')}</td></tr>`).join(''))}` }

export function renderProviders(content,period,branch="General"){
 const searchKey=`blunno-provider-search-${period}-${branch}`,sortKey=`blunno-provider-sort-${period}-${branch}`;
 const searchText=localStorage.getItem(searchKey)||'';
 const sortMode=localStorage.getItem(sortKey)||'name';
 const invoices=rows('invoices',period,branch),totals=new Map(),dailyByProvider=new Map(),providerNames=new Map();
 invoices.forEach(x=>{const name=Store.invoiceProviderName(x)||x.provider||'Sin proveedor',key=sourceIdentity(name);providerNames.set(key,name);totals.set(key,(totals.get(key)||0)+Number(x.amount||0));const date=x.operationDate||x.date;const dm=dailyByProvider.get(key)||new Map();dm.set(date,(dm.get(date)||0)+Number(x.amount||0));dailyByProvider.set(key,dm)});
 const amountFor=p=>totals.get(sourceIdentity(p.name))||0;
 const data=rows('providers').map(x=>({...x,branchId:null}));
 data.sort((a,b)=>{const amountDiff=amountFor(a)-amountFor(b);if(sortMode==='amount-desc'&&amountDiff!==0)return -amountDiff;if(sortMode==='amount-asc'&&amountDiff!==0)return amountDiff;return String(a.name).localeCompare(String(b.name),'es',{sensitivity:'base'});});
 const days=daysInPeriod(period);
 const matrix=data.map(p=>{const key=sourceIdentity(p.name),dm=dailyByProvider.get(key)||new Map();const cells=Array.from({length:days},(_,i)=>{const v=dm.get(isoDate(period,i+1))||0;return `<td>${v?money(v):'—'}</td>`}).join('');return `<tr data-provider-searchable="${esc(p.name)}" data-provider-search-key="${esc(key)}"><th class="sticky-col"><b>${esc(p.name)}</b></th>${cells}<td class="total-cell">${money(amountFor(p))}</td></tr>`}).join('');
 const providerRow=(x)=>{const key=sourceIdentity(x.name),available=providerAvailableInBranch(x,branch),total=amountFor(x);return `<article class="provider-mobile-card" data-provider-mobile-card="${esc(x.name)}" data-provider-searchable="${esc(x.name)}" data-provider-search-key="${esc(key)}"><div class="provider-mobile-head"><div class="provider-mobile-identity"><span class="provider-mobile-avatar">${esc((x.name||'?').trim().charAt(0).toUpperCase())}</span><div><h3>${esc(x.name)}</h3><span class="status-pill ${x.active===false?'muted':'success'}">${x.active===false?'INACTIVO':'ACTIVO'}</span></div></div><div class="provider-mobile-total"><small>Facturado en ${esc(periodLabel(period))}</small><strong>${money(total)}</strong></div></div><div class="provider-mobile-facts"><div><span>Estado</span><b>${x.active===false?'Inactivo':'Activo'}</b></div><div><span>Disponibilidad</span><b class="${branch==='General'||available?'provider-available':'provider-unavailable'}">${branch==='General'?'Todos los locales':available?'Disponible':'No disponible'}</b></div></div><div class="provider-mobile-actions">${actions('providers',x.id,'provider')}<button type="button" class="secondary-button compact-button" data-provider-history="${esc(x.name)}">Historial</button>${branch!=='General'?`<button type="button" class="secondary-button compact-button" data-provider-branch-toggle="${esc(x.id)}" data-provider-branch="${esc(branch)}" data-provider-available="${available?'1':'0'}">${available?'Quitar de este local':'Agregar a este local'}</button>`:''}</div></article>`};
 const mobileMatrix=data.filter(p=>dailyByProvider.has(sourceIdentity(p.name))).map(p=>{const key=sourceIdentity(p.name),dm=dailyByProvider.get(key)||new Map();const entries=[...dm.entries()].filter(([,v])=>Number(v)!==0).sort(([a],[b])=>String(a).localeCompare(String(b)));return `<article class="provider-matrix-mobile-card" data-provider-mobile-card="${esc(p.name)}" data-provider-searchable="${esc(p.name)}" data-provider-search-key="${esc(key)}"><div class="provider-matrix-mobile-head"><strong>${esc(p.name)}</strong><b>${money(amountFor(p))}</b></div>${entries.length?`<div class="provider-mobile-day-values">${entries.map(([date,value])=>`<div><span>Día ${String(date).slice(-2)}</span><strong>${money(value)}</strong></div>`).join('')}</div>`:'<p>Sin importes diarios registrados.</p>'}</article>`}).join('')||'<div class="empty-block">No hay facturación de proveedores en este período.</div>';
 const suggestionNames=[...new Map(data.map(p=>[sourceIdentity(p.name),p.name])).values()];
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">MAESTRO PERMANENTE</span><b>Proveedores</b><small>Los nombres permanecen entre meses. Las facturas son movimientos independientes.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><div class="page-intro"><div><h2>Proveedores</h2><p>Buscá mientras escribís o cambiá el orden según el total facturado del período.</p></div><div class="page-actions"><button class="secondary-button" data-pdf-close="providers">PDF</button><button class="primary-button" data-new="provider">＋ Nuevo proveedor</button></div></div><div class="provider-tools"><label class="provider-search-control"><span>Buscar proveedor</span><div class="provider-search-input-wrap"><input type="search" id="providerSearchInput" value="${esc(searchText)}" placeholder="Escribí, por ejemplo, co…" autocomplete="off" aria-autocomplete="list" aria-controls="providerSearchSuggestions"><button type="button" id="providerSearchClear" aria-label="Limpiar búsqueda" title="Limpiar búsqueda">×</button></div><div id="providerSearchSuggestions" class="provider-search-suggestions hidden" role="listbox"></div></label><label class="provider-sort-control"><span>Ordenar por</span><select id="providerSortFilter"><option value="name" ${sortMode==='name'?'selected':''}>Orden alfabético</option><option value="amount-desc" ${sortMode==='amount-desc'?'selected':''}>Mayor monto</option><option value="amount-asc" ${sortMode==='amount-asc'?'selected':''}>Menor monto</option></select></label><small class="provider-tools-hint">Los montos corresponden a las facturas del mes y sucursal seleccionados.</small></div><div class="provider-search-empty empty-block" id="providerSearchEmpty" hidden>No encontramos ese proveedor. Probá con otras letras o limpiá la búsqueda.</div><div class="providers-desktop-view">${table(['Proveedor','Facturado en período','Estado maestro','Disponibilidad en este local','Acciones'],data.map(x=>`<tr data-provider-searchable="${esc(x.name)}" data-provider-search-key="${esc(sourceIdentity(x.name))}"><td><b>${esc(x.name)}</b></td><td>${money(amountFor(x))}</td><td><span class="status-pill ${x.active===false?'muted':''}">${x.active===false?'INACTIVO':'ACTIVO'}</span></td><td>${branch==='General'?'<span class="status-pill success">TODOS LOS LOCALES</span>':`<span class="status-pill ${providerAvailableInBranch(x,branch)?'success':'warning'}">${providerAvailableInBranch(x,branch)?'DISPONIBLE':'NO DISPONIBLE'}</span>`}</td><td>${actions('providers',x.id,'provider')}<button class="secondary-button compact-button" data-provider-history="${esc(x.name)}">Historial</button>${branch!=='General'?`<button class="secondary-button compact-button" data-provider-branch-toggle="${esc(x.id)}" data-provider-branch="${esc(branch)}" data-provider-available="${providerAvailableInBranch(x,branch)?'1':'0'}">${providerAvailableInBranch(x,branch)?'Quitar de este local':'Agregar a este local'}</button>`:''}</td></tr>`).join(''))}</div><div class="providers-mobile-view"><div class="bulk-toolbar provider-mobile-bulk"><span>Seleccioná proveedores para operar en conjunto.</span><button class="danger-button" data-bulk-delete="providers">Enviar seleccionados a papelera</button></div><div class="providers-mobile-cards">${data.map(providerRow).join('')||'<div class="empty-block">No hay proveedores para mostrar.</div>'}</div></div><section class="panel provider-matrix-section"><div class="panel-head"><div><span class="section-kicker">PLANILLA</span><h3>Proveedor × día · ${periodLabel(period)}</h3></div></div><div class="sheet-wrap providers-matrix-desktop"><table class="hours-sheet provider-matrix"><thead><tr><th class="sticky-col">Proveedor</th>${Array.from({length:days},(_,i)=>`<th>${i+1}</th>`).join('')}<th>TOTAL</th></tr></thead><tbody>${matrix}</tbody></table></div><div class="providers-matrix-mobile">${mobileMatrix}</div></section>`;
 window.__blunnoProviderSuggestionNames=suggestionNames;
}
export function renderInvoices(content,period,branch="General"){
 const allData=rows('invoices',period,branch).map((x,index)=>({...x,_loadIndex:index}));
 // Store.add inserts each new movement at the beginning; load timestamps cover imports and legacy ordering.
 allData.sort((a,b)=>String(b.loadDate||b.createdAt||'').localeCompare(String(a.loadDate||a.createdAt||''))||a._loadIndex-b._loadIndex);
 const providerNames=new Map();allData.forEach(x=>{const name=Store.invoiceProviderName(x)||x.provider||'Sin proveedor';providerNames.set(sourceIdentity(name),name)});
 const providers=[...providerNames.entries()].sort((a,b)=>a[1].localeCompare(b[1],'es',{sensitivity:'base'}));
 const filterKey=`blunno-invoice-provider-${period}-${branch}`;
 let selectedProvider=localStorage.getItem(filterKey)||'ALL';
 if(selectedProvider!=='ALL'&&!providerNames.has(selectedProvider)){selectedProvider='ALL';localStorage.setItem(filterKey,'ALL')}
 const data=selectedProvider==='ALL'?allData:allData.filter(x=>sourceIdentity(Store.invoiceProviderName(x)||x.provider||'Sin proveedor')===selectedProvider);
 const total=data.reduce((s,x)=>s+Number(x.amount||0),0);
 const desktop=table(['Proveedor','Factura','Movimiento','Carga','Sucursal','Importe','Estado','Acciones'],data.map(x=>`<tr><td><b>${esc(Store.invoiceProviderName(x)||x.provider)}</b></td><td>${esc(x.number||'—')}</td><td>${dateLabel(x.operationDate||x.date)}</td><td>${dateTimeLabel(x.loadDate||x.createdAt)}</td><td>${esc(x.branch)}</td><td class="amount clickable" data-detail="invoices" data-id="${x.id}">${money(x.amount)}</td><td><span class="status-pill success">CARGADA</span></td><td>${actions('invoices',x.id,'invoice')}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No hay facturas para este filtro en el período seleccionado.</td></tr>');
 const mobile=data.map(x=>`<article class="invoice-mobile-card"><div class="invoice-mobile-card-head"><div class="invoice-mobile-provider"><span>PROVEEDOR</span><strong>${esc(Store.invoiceProviderName(x)||x.provider||'Sin proveedor')}</strong><small>Factura ${esc(x.number||'—')}</small></div><button type="button" class="invoice-mobile-amount" data-detail="invoices" data-id="${esc(x.id)}"><span>IMPORTE</span><b>${money(x.amount)}</b><small>Ver detalle</small></button></div><div class="invoice-mobile-facts"><div><span>Fecha de movimiento</span><b>${dateLabel(x.operationDate||x.date)}</b></div><div><span>Fecha de carga</span><b>${dateTimeLabel(x.loadDate||x.createdAt)}</b></div><div><span>Sucursal</span><b>${esc(x.branch||'—')}</b></div><div><span>Estado</span><b class="invoice-loaded-state">CARGADA</b></div></div><div class="invoice-mobile-actions">${actions('invoices',x.id,'invoice')}</div></article>`).join('')||'<div class="empty-block">No hay facturas para este filtro en el período seleccionado.</div>';
 const mobileBulk=branch==='General'?'':`<div class="bulk-toolbar invoice-mobile-bulk"><span>Seleccioná facturas para operar en conjunto.</span><button class="danger-button" data-bulk-delete="invoices">Enviar seleccionadas a papelera</button></div>`;
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">FACTURAS · CARGA Y CONTROL</span><b>${esc(branch)}</b><small>Se muestran primero las últimas facturas cargadas, independientemente de su fecha de movimiento.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><section class="panel quick-invoice"><div class="panel-head"><div><span class="section-kicker">CARGA EXPRESS</span><h3>Una factura en segundos</h3></div></div>${branch==='General'?`<div class="notice warning">Elegí una sucursal concreta arriba para cargar facturas.</div>`:`<div class="quick-invoice-grid"><div class="provider-picker quick-provider-picker"><div class="provider-picker-line"><input id="quickInvoiceProvider" autocomplete="off" placeholder="Proveedor" aria-label="Proveedor" role="combobox" aria-autocomplete="list"><input id="quickInvoiceProviderId" type="hidden" data-provider-id-field><button type="button" class="provider-picker-toggle" aria-label="Mostrar proveedores" aria-expanded="false">⌄</button></div><div class="provider-suggestions hidden"></div></div><input id="quickInvoiceNumber" placeholder="N° factura" aria-label="Número de factura"><input id="quickInvoiceDate" type="date" min="${period}-01" max="${period}-${String(daysInPeriod(period)).padStart(2,'0')}" value="${defaultMovementDate(period)}" aria-label="Fecha de movimiento"><input id="quickInvoiceAmount" inputmode="decimal" placeholder="Importe" aria-label="Importe"><button class="primary-button" data-invoice-quick-save>Guardar factura</button></div><div class="quick-hint">Ejemplo: Aguilera · 0001-00012345 · fecha · $ 125.000</div>`}</section><div class="page-intro"><div><h2>Facturas</h2><p>Cada factura conserva fecha de movimiento, fecha de carga, sucursal, responsable y auditoría. La misma numeración puede repetirse en distintas sucursales.</p></div><button class="secondary-button" data-pdf-close="invoices">PDF</button></div><div class="invoice-filter-bar"><label class="invoice-provider-filter">Proveedor<select id="invoiceProviderFilter"><option value="ALL" ${selectedProvider==='ALL'?'selected':''}>Todos los proveedores</option>${providers.map(([key,name])=>`<option value="${esc(key)}" ${selectedProvider===key?'selected':''}>${esc(name)}</option>`).join('')}</select></label><small>El filtro muestra únicamente las facturas de este mes y de la sucursal seleccionada.</small></div><div class="mini-kpis">${kpi('Total visible',money(total))}${kpi('Facturas visibles',data.length)}${kpi('Proveedores',new Set(data.map(x=>sourceIdentity(Store.invoiceProviderName(x)||x.provider))).size)}</div><div class="invoices-desktop-view">${desktop}</div><div class="invoices-mobile-view">${mobileBulk}<div class="invoices-mobile-list">${mobile}</div></div>`;
}
function canonicalExpenseCategory(value){const key=sourceIdentity(value);return CONFIG.expenseCategories.find(c=>sourceIdentity(c)===key)||'';}
export function renderExpenses(content,period,branch="General"){
 const allData=rows('expenses',period,branch);
 let selectedCategory=localStorage.getItem(`blunno-expense-category-${period}-${branch}`)||"ALL";
 if(selectedCategory!=='ALL'){selectedCategory=canonicalExpenseCategory(selectedCategory)||"ALL";localStorage.setItem(`blunno-expense-category-${period}-${branch}`,selectedCategory);}
 const data=selectedCategory==='ALL'?allData:allData.filter(x=>canonicalExpenseCategory(x.category)===selectedCategory);
 const total=allData.reduce((s,x)=>s+Number(x.amount||0),0);
 const cats=CONFIG.expenseCategories.map(c=>[c,allData.filter(x=>canonicalExpenseCategory(x.category)===c).reduce((s,x)=>s+Number(x.amount||0),0)]).filter(x=>x[1]);
 const categoryPdf=selectedCategory!=='ALL'?`<button type="button" class="secondary-button" data-expense-selected-category-pdf>Descargar PDF · ${esc(selectedCategory)}</button>`:'';
 const desktopRows=data.map(x=>`<tr><td>${dateLabel(x.date)}<small class="cell-note">Cargado: ${dateTimeLabel(x.createdAt||`${x.date}T12:00:00`)}</small></td><td><b>${esc(x.category)}</b></td><td>${esc(x.concept)}</td><td>${esc(x.branch)}</td><td class="amount">${money(x.amount)}</td><td>${esc(x.responsible)}</td><td>${branch==='General'?`<div class="row-actions"><button class="secondary-button compact-button" data-detail="expenses" data-id="${esc(x.id)}">Ver</button></div>`:`<div class="row-actions"><input type="checkbox" aria-label="Seleccionar" data-bulk-select="expenses" data-id="${esc(x.id)}"><button type="button" data-expense-edit="${esc(x.id)}">Editar</button><button type="button" class="danger-link" data-delete="expenses" data-id="${esc(x.id)}">Eliminar</button></div>`}</td></tr>`).join('');
 const mobileCards=data.map(x=>`<article class="expense-mobile-card"><div class="expense-mobile-card-head"><div class="expense-mobile-date"><span>FECHA</span><b>${dateLabel(x.date)}</b><small class="expense-mobile-load-date">Cargado: ${dateTimeLabel(x.createdAt||`${x.date}T12:00:00`)}</small></div><div class="expense-mobile-amount"><span>IMPORTE</span><strong>${money(x.amount)}</strong></div></div><div class="expense-mobile-card-body"><span class="expense-mobile-category">${esc(x.category||'Sin categoría')}</span><h3>${esc(x.concept||'Gasto sin detalle')}</h3><div class="expense-mobile-meta"><div><span>Sucursal</span><b>${esc(x.branch||'—')}</b></div><div><span>Responsable</span><b>${esc(x.responsible||'—')}</b></div></div></div><div class="expense-mobile-card-actions">${branch==='General'?`<button type="button" class="secondary-button compact-button" data-detail="expenses" data-id="${esc(x.id)}">Ver detalle</button>`:`<label class="expense-mobile-select"><input type="checkbox" aria-label="Seleccionar gasto" data-bulk-select="expenses" data-id="${esc(x.id)}"><span>Seleccionar</span></label><button type="button" class="secondary-button compact-button" data-expense-edit="${esc(x.id)}">Editar</button><button type="button" class="danger-button compact-button" data-delete="expenses" data-id="${esc(x.id)}">Eliminar</button>`}</div></article>`).join('')||'<div class="empty-block expense-mobile-empty">No hay gastos en esta categoría para el período seleccionado.</div>';
 const mobileBulk=branch==='General'?'':`<div class="bulk-toolbar expense-mobile-bulk"><label><input type="checkbox" data-bulk-select-all="expenses"> Seleccionar todos</label><button class="danger-button" data-bulk-delete="expenses">Enviar seleccionados a papelera</button></div>`;
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">GASTOS DEL LOCAL</span><b>${esc(branch)}</b><small>Categorías y movimientos del período seleccionado.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><div class="page-intro"><div><h2>Gastos por categoría</h2><p>Consultá los gastos por rubro. Los últimos cargados aparecen primero, sin importar la fecha del gasto.</p></div><div class="page-actions">${categoryPdf}<button class="secondary-button" data-pdf-close="expenses">Descargar PDF general</button><button class="primary-button" data-new="expense">＋ Nuevo gasto</button></div></div><div class="mini-kpis">${kpi('Total gastos',money(total))}${kpi('Movimientos',allData.length)}${kpi('Categorías usadas',cats.length)}</div><section class="panel expense-history-panel"><div class="panel-head"><div><span class="section-kicker">HISTORIAL POR CATEGORÍA</span><h3>${selectedCategory==='ALL'?'Todos los movimientos':`Gastos · ${esc(selectedCategory)}`}</h3></div><label class="field-inline">Categoría<select id="expenseCategoryFilter"><option value="ALL" ${selectedCategory==='ALL'?'selected':''}>Todas</option>${CONFIG.expenseCategories.map(c=>`<option value="${esc(c)}" ${selectedCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><p>Seleccioná una categoría para ver únicamente sus movimientos del local y del período. La opción Descargar PDF genera solo ese rubro.</p><div class="expense-filter-chips">${cats.map(([c,v])=>`<button type="button" class="expense-filter-chip ${selectedCategory===c?'active':''}" data-expense-category="${esc(c)}"><span>${esc(c)}</span><b>${money(v)}</b></button>`).join('')}</div></section><div class="expenses-desktop-view">${table(['Fecha','Categoría','Detalle','Sucursal','Importe','Responsable','Acciones'],desktopRows,'No hay gastos en esta categoría para el período seleccionado.')}</div><div class="expenses-mobile-view">${mobileBulk}<div class="expenses-mobile-list">${mobileCards}</div></div>`;
}
export function renderPeople(content,period,branch="General"){
 const data=rows('employees').filter(x=>branch==='General'||x.branch===branch).sort((a,b)=>String(a.name).localeCompare(String(b.name),'es'));
 const desktop=table(['Empleado','Sucursal','Puesto','Valor hora','Estado','Acciones'],data.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.branch)}</td><td>${esc(x.role||'—')}</td><td>${money(x.hourlyRate)}</td><td><span class="status-pill ${x.active===false?'muted':''}">${x.active===false?'INACTIVO':'ACTIVO'}</span></td><td>${actions('employees',x.id,'employee')}</td></tr>`).join(''));
 const mobile=data.map(x=>`<article class="employee-card people-mobile-card"><div class="employee-card-top"><div class="employee-avatar">${esc((x.name||'—').trim().charAt(0).toUpperCase())}</div><div class="employee-card-identity"><h4>${esc(x.name)}</h4><span class="employee-status ${x.active===false?'inactive':''}">${x.active===false?'INACTIVO':'ACTIVO'}</span></div><div class="employee-mobile-rate"><small>VALOR HORA</small><strong>${money(x.hourlyRate||0)}</strong></div></div><div class="employee-facts"><div><span>Sucursal</span><strong>${esc(x.branch||'—')}</strong></div><div><span>Puesto</span><strong>${esc(x.role||'—')}</strong></div></div><div class="employee-actions">${actions('employees',x.id,'employee')}<button type="button" class="secondary-button compact-button" data-view-jump="hours" data-hours-employee="${esc(x.id)}">Ver horas</button></div></article>`).join('')||'<div class="empty-block">No hay empleados asignados a esta sucursal.</div>';
 const mobileBulk=branch==='General'?'':`<div class="bulk-toolbar people-mobile-bulk"><span>Seleccioná empleados para operar en conjunto.</span><button class="danger-button" data-bulk-delete="employees">Enviar seleccionados a papelera</button></div>`;
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">PERSONAL</span><b>${esc(branch)}</b><small>Las fichas pertenecen a una sucursal y no se mezclan.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><div class="page-intro"><div><h2>Personal</h2><p>Valor hora individual, estado y sucursal.</p></div><div class="page-actions"><button class="secondary-button" data-pdf-close="people">PDF</button><button class="primary-button" data-new="employee">＋ Nuevo empleado</button></div></div><div class="people-desktop-view">${desktop}</div><div class="people-mobile-view">${mobileBulk}<div class="people-mobile-list">${mobile}</div></div>`;
}
function weekCells(period,employee,branch){const days=daysInPeriod(period);let html='';for(let d=1;d<=days;d++){const date=isoDate(period,d), r=Store.list('hours',period,branch).find(x=>x.employeeId===employee.id&&x.date===date);const dow=new Date(`${date}T12:00:00`).toLocaleDateString('es-AR',{weekday:'short'}).replace('.','');html+=`<td class="hour-cell" data-hour-date="${date}" data-employee="${employee.id}"><span>${dow}</span><input inputmode="decimal" value="${r?esc(r.hours):''}" placeholder="–" data-hour-input></td>`}return html;}

export function renderHours(content,period,branch="General"){
 const allEmployees=Store.list('employees').filter(e=>e.active!==false&&(branch==='General'||e.branch===branch)).sort((a,b)=>a.name.localeCompare(b.name,'es'));
 const savedEmployee=localStorage.getItem('blunno-hours-employee')||'ALL';
 const selectedEmployee=allEmployees.some(e=>e.id===savedEmployee)?savedEmployee:'ALL';
 const employees=allEmployees.filter(e=>selectedEmployee==='ALL'||e.id===selectedEmployee);
 const data=Store.list('hours',period,branch);
 const days=daysInPeriod(period);
 const lastWeek=Math.max(1,Math.ceil(days/7));
 const editable=branch!=='General';
 const disabledAttr=editable?'':'disabled';
 let selectedWeek=Number(localStorage.getItem(`blunno-hours-week-${period}-${branch}`)||1);
 if(!Number.isFinite(selectedWeek)||selectedWeek<1)selectedWeek=1;
 if(selectedWeek>lastWeek)selectedWeek=lastWeek;
 const weekStart=(selectedWeek-1)*7+1;
 const weekEnd=Math.min(days,weekStart+6);
 const weekDates=Array.from({length:weekEnd-weekStart+1},(_,i)=>weekStart+i);
 const currentRows=Store.list('hours',period,branch);
 const getRow=(employeeId,date)=>currentRows.find(x=>x.employeeId===employeeId&&x.date===date);
 const valueFor=e=>{const rs=currentRows.filter(x=>x.employeeId===e.id);const worked=rs.reduce((s,x)=>s+Number(x.hours||0),0),holiday=rs.filter(x=>x.holiday==='yes').reduce((s,x)=>s+Number(x.hours||0),0),sunday=rs.filter(x=>x.holiday!=='yes'&&new Date(`${x.date}T12:00:00`).getDay()===0).reduce((s,x)=>s+Number(x.hours||0),0);return {normal:Math.max(0,worked-holiday-sunday),sunday,holiday,overtime:rs.reduce((s,x)=>s+Number(x.overtimeHours||0),0),advance:rs.reduce((s,x)=>s+Number(x.advance||0),0),merch:rs.reduce((s,x)=>s+Number(x.merchandise||0),0)};};
 const totals={normal:0,sunday:0,holiday:0,overtime:0,advance:0,merch:0}; employees.forEach(e=>{const v=valueFor(e);Object.keys(totals).forEach(k=>totals[k]+=v[k]);});
 const weekLabel=weekStart===weekEnd?`Día ${weekStart}`:`Días ${weekStart} - ${weekEnd}`;
 const nav=(dir,disabled)=>`<button class="secondary-button" data-hours-week="${dir}" ${disabled?'disabled':''}>${dir==='prev'?'← Semana anterior':'Siguiente semana →'}</button>`;
 const header=weekDates.map(d=>{const date=isoDate(period,d),dt=new Date(`${date}T12:00:00`);return `<th class="hours-day-head"><span>${dt.toLocaleDateString('es-AR',{weekday:'short'}).replace('.','')}</span><b>${String(d).padStart(2,'0')}</b></th>`}).join('');
 const rowsHtml=employees.map(e=>{const v=valueFor(e);return `<tr><th class="hours-employee-col"><strong>${esc(e.name)}</strong><small>${esc(e.branch||'—')}</small></th>${weekDates.map(d=>{const date=isoDate(period,d),r=getRow(e.id,date),franco=r?.status==='franco',feriadoNoTrabajado=!franco&&(r?.status==='feriado'||r?.status==='holiday-rest'||(r?.holiday==='yes'&&/^f$/i.test(String(r?.displayValue||'')))),feriadoTrabajado=r?.holiday==='yes'&&!feriadoNoTrabajado;return `<td class="hours-entry-cell ${feriadoTrabajado?'holiday-cell':''} ${feriadoNoTrabajado?'feriado-cell':''} ${franco?'franco-cell':''}"><div class="hours-cell-stack"><label><span>Horas</span><input data-hour-field="hours" data-hour-date="${date}" data-employee="${e.id}" value="${esc(franco?'FRANCO':(r?.displayValue??''))}" placeholder="—" inputmode="text" autocapitalize="characters" autocomplete="off" title="Número de horas · F = feriado rojo · 8H = feriado trabajado amarillo · FRANCO = descanso" ${disabledAttr}></label><label class="overtime-mini"><span>Extras</span><input data-hour-field="overtime" data-hour-date="${date}" data-employee="${e.id}" value="${r?.overtimeHours?esc(r.overtimeHours):''}" placeholder="0" inputmode="decimal" title="Horas extras manuales" ${disabledAttr}></label></div></td>`}).join('')}<td class="week-total-cell"><strong>${number(v.normal+v.sunday+v.holiday+v.overtime)}</strong><small>total mes</small></td></tr>`}).join('');
 const summaryRows=employees.map(e=>{const v=valueFor(e);return `<tr><td><b>${esc(e.name)}</b><small class="cell-note">${esc(e.branch||'—')}</small></td><td>${number(v.normal)}</td><td>${number(v.sunday)}</td><td>${number(v.holiday)}</td><td>${number(v.overtime)}</td><td class="amount">${number(v.normal+v.sunday+v.holiday+v.overtime)}</td><td>${money(v.advance)}</td><td>${money(v.merch)}</td><td>${editable?`<button class="primary-button compact-button" data-liquidate="${e.id}">Totalizar sueldo</button>`:`<span class="status-pill muted">Solo consulta</span>`}</td></tr>`}).join('');
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">HORAS MENSUALES · PLANILLA</span><b>${esc(branch)}</b><small>Planilla compacta por semana. F = feriado no trabajado (rojo), 8H = horas trabajadas en feriado (amarillo) y FRANCO = descanso.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><div class="page-intro"><div><h2>Horas mensuales</h2><p>Semana ${selectedWeek} de ${lastWeek} · ${weekLabel}. Enter guarda la celda y pasa al siguiente día.</p></div><div class="page-actions"><button class="secondary-button" data-open-holidays>Feriados</button><button class="secondary-button" data-pdf-close="hours">Generar PDF</button>${editable?'<button class="primary-button" data-new="hours">＋ Carga manual</button>':''}</div></div><section class="panel hours-control-panel"><div class="hours-control-main"><div><span class="section-kicker">PERÍODO ACTIVO</span><strong>${periodLabel(period)}</strong><span>${employees.length} empleado${employees.length===1?'':'s'} visible${employees.length===1?'':'s'}</span></div><label class="hours-filter">Empleado<select id="hoursEmployeeFilter"><option value="ALL" ${selectedEmployee==='ALL'?'selected':''}>Todos los empleados</option>${allEmployees.map(e=>`<option value="${e.id}" ${selectedEmployee===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label></div><div class="hours-week-nav">${nav('prev',selectedWeek===1)}<div class="hours-week-current"><span>Semana ${selectedWeek}</span><b>${weekLabel}</b></div>${nav('next',selectedWeek===lastWeek)}</div></section><section class="panel"><div class="panel-head"><div><span class="section-kicker">CARGA RÁPIDA</span><h3>${weekLabel}</h3><p>Las horas extras se cargan en su propio casillero y se guardan en el mismo registro diario.</p></div></div><div class="table-wrap hours-v20-wrap"><table class="hours-v20-table"><thead><tr><th class="hours-employee-col">Empleado</th>${header}<th class="hours-total-col">Total</th></tr></thead><tbody>${rowsHtml||`<tr><td colspan="${weekDates.length+2}" class="empty">No hay empleados asignados a ${esc(branch)}.</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><span class="section-kicker">RESUMEN MENSUAL</span><h3>Totales para liquidación</h3></div></div><div class="hours-summary-strip"><div><span>Horas normales</span><strong>${number(totals.normal)}</strong></div><div><span>Horas domingo</span><strong>${number(totals.sunday)}</strong></div><div><span>Horas feriado</span><strong>${number(totals.holiday)}</strong></div><div><span>Horas extras</span><strong>${number(totals.overtime)}</strong></div><div><span>Total cargado</span><strong>${number(totals.normal+totals.sunday+totals.holiday+totals.overtime)}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Empleado</th><th>Normales</th><th>Domingo</th><th>Feriado</th><th>Extras</th><th>Total</th><th>Adelantos</th><th>Mercadería</th><th>Liquidación</th></tr></thead><tbody>${summaryRows||'<tr><td colspan="9" class="empty">No hay datos para resumir.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><span class="section-kicker">REFERENCIA</span><h3>Cómo cargar las celdas</h3></div></div><div class="legend-row"><span><b>8</b> horas normales</span><span><b>F</b> feriado sin trabajar · rojo</span><span><b>8H</b> horas trabajadas en feriado · amarillo</span><span><b>FRANCO</b> descanso legado · gris</span><span><b>Extras</b> se ingresa manualmente</span><span><b>Enter</b> guarda y avanza</span></div></section>`;
}

export function renderInvestments(content,period,branch="General"){
 const data=rows('investments',period,branch);
 const total=data.reduce((sum,x)=>sum+Number(x.amount||0),0);
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">GASTOS DE INVERSIÓN</span><b>${esc(branch)}</b><small>Cada sucursal conserva su propia cuenta; General consolida sin mezclar registros.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><div class="page-intro"><div><h2>Inversiones</h2><p>Los últimos movimientos cargados aparecen primero. La fecha de carga se muestra por separado.</p></div><div class="page-actions"><button class="secondary-button" data-pdf-close="investments">Generar PDF</button><button class="secondary-button" data-print-investments>Imprimir historial</button><button class="primary-button" data-new="investment">＋ Nueva inversión</button></div></div><div class="mini-kpis">${kpi('Invertido',money(total))}${kpi('Movimientos',data.length)}${kpi('Período',periodLabel(period))}</div>${table(['Fecha de inversión / carga','Resumen','Sucursal','Importe','Comprobante','Responsable','Acciones'],data.map(x=>`<tr><td>${dateLabel(x.date)}<small class="cell-note">Cargado: ${dateTimeLabel(x.createdAt||`${x.date}T12:00:00`)}</small></td><td><b>${esc(x.concept)}</b><small class="cell-note">${esc(x.notes||'')}</small></td><td>${esc(x.branch)}</td><td class="amount">${money(x.amount)}</td><td>${esc(x.document||'—')}</td><td>${esc(x.responsible||'—')}</td><td>${branch==='General'?`<div class="row-actions"><button class="secondary-button compact-button" data-detail="investments" data-id="${esc(x.id)}">Ver</button></div>`:`<div class="row-actions"><input type="checkbox" aria-label="Seleccionar" data-bulk-select="investments" data-id="${esc(x.id)}"><button type="button" data-investment-edit="${esc(x.id)}">Modificar</button><button type="button" class="danger-link" data-delete="investments" data-id="${esc(x.id)}">Eliminar</button></div>`}</td></tr>`).join(''))}`;
}

export function renderResults(content,period,branch="General"){
 const s=Store.summary(period,branch); const byCat=CONFIG.expenseCategories.map(c=>[c,rows('expenses',period,branch).filter(x=>x.category===c).reduce((a,x)=>a+Number(x.amount||0),0)]).filter(x=>x[1]);
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">RESULTADOS</span><b>${esc(branch)}</b><small>Ingresos, gastos, proveedores, inversiones y personal separados.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><div class="page-intro"><div><h2>Resultado mensual</h2><p>El resultado se calcula con la estructura real del negocio.</p></div><button class="secondary-button" data-pdf-close="results">Descargar PDF</button></div><div class="result-grid">${[['Ingresos',s.income,'good'],['Gastos operativos',s.totalExpenses,s.result>=0?'':'bad'],['Proveedores',s.providers,''],['Inversiones',s.investment,''],['Personal estimado',s.salary,''],['Resultado',s.result,s.result>=0?'good':'bad']].map(x=>`<div class="result-card"><span>${x[0]}</span><strong class="${x[2]}">${money(x[1])}</strong><p>${x[0]==='Resultado'?'Ingresos menos gastos operativos, inversión y costo estimado de horas.':''}</p></div>`).join('')}</div><section class="panel"><div class="panel-head"><div><span class="section-kicker">GASTOS</span><h3>Distribución por categoría</h3></div></div>${table(['Categoría','Monto','% de gastos'],byCat.map(([c,v])=>`<tr><td><b>${esc(c)}</b></td><td>${money(v)}</td><td>${s.totalExpenses?((v/s.totalExpenses)*100).toFixed(1):0}%</td></tr>`).join(''))}</section>`;
}

export function renderCompare(content,period,branch="General",compareA=prevPeriod(period),compareB=period){
 const periods=[...new Set([period,prevPeriod(period),...Store.db.periods.map(x=>x.id)])].sort().reverse();
 const calc=p=>Store.summary(p,branch); const a=calc(compareA),b=calc(compareB); const pct=(x,y)=>x===0?(y===0?0:100):((y-x)/Math.abs(x))*100; const line=(l,x,y)=>`<tr><td><b>${l}</b></td><td>${money(x)}</td><td>${money(y)}</td><td>${money(y-x)}</td><td class="${y-x>=0?'up':'down'}">${pct(x,y)>=0?'+':''}${pct(x,y).toFixed(1)}%</td></tr>`;
 content.innerHTML=`<div class="page-intro"><div><span class="section-kicker">COMPARATIVAS</span><h2>Comparación de períodos</h2><p>Elegí dos meses distintos; también podés ver la evolución de seis meses.</p></div><button class="secondary-button" data-pdf-close="compare">Descargar PDF</button></div><div class="compare-controls"><label>Período A<select data-compare-select="a">${periods.map(p=>`<option value="${p}" ${p===compareA?'selected':''}>${periodLabel(p)}</option>`).join('')}</select></label><span>vs.</span><label>Período B<select data-compare-select="b">${periods.map(p=>`<option value="${p}" ${p===compareB?'selected':''}>${periodLabel(p)}</option>`).join('')}</select></label></div><div class="profile-bar compact"><div><b>Perfil: ${esc(branch)}</b></div><div class="profile-chips">${branchFilter(branch)}</div></div>${table(['Indicador',periodLabel(compareA),periodLabel(compareB),'Diferencia','Variación'],[line('Ingresos',a.income,b.income),line('Gastos',a.totalExpenses,b.totalExpenses),line('Resultado',a.result,b.result),line('Proveedores',a.providers,b.providers),line('Inversiones',a.investment,b.investment),line('Horas',a.hours,b.hours)].join(''))}<section class="panel"><div class="panel-head"><div><span class="section-kicker">EVOLUCIÓN</span><h3>Últimos 6 meses desde ${periodLabel(compareB)}</h3></div></div><div class="bar-chart">${Array.from({length:6},(_,i)=>{const [y,m]=compareB.split('-').map(Number);const d=new Date(y,m-1-i,1),p=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,s=calc(p);return `<div class="bar-item"><div class="bar-track"><div class="bar-fill" style="height:${Math.min(100,Math.abs(s.result)/(Math.max(1,...Array.from({length:6},(_,j)=>{const dd=new Date(y,m-1-j,1),pp=`${dd.getFullYear()}-${String(dd.getMonth()+1).padStart(2,'0')}`;return Math.abs(calc(pp).result)})))*100)}%"></div></div><b>${p.slice(5)}</b><span>${money(s.result)}</span></div>`}).reverse().join('')}</div></section>`;
}

export function renderTasks(content){const all=Store.list('tasks').sort((a,b)=>`${a.dueDate} ${a.dueTime}`.localeCompare(`${b.dueDate} ${b.dueTime}`));const pending=all.filter(x=>x.status!=='completed'),done=all.filter(x=>x.status==='completed');content.innerHTML=`<div class="page-intro"><div><span class="section-kicker">CENTRO DE ATENCIÓN</span><h2>Recordatorios</h2><p>Las tareas viven dentro de Blunno. Completar una tarea también queda auditado.</p></div><button class="primary-button" data-new="task">＋ Nuevo recordatorio</button></div><div class="task-columns"><section class="panel"><h3>Pendientes</h3>${pending.map(t=>taskCard(t)).join('')||'<div class="empty-block">No hay tareas pendientes.</div>'}</section><section class="panel"><h3>Completadas</h3>${done.slice(0,20).map(t=>taskCard(t,true)).join('')||'<div class="empty-block">Todavía no hay tareas completadas.</div>'}</section></div>`}
function taskCard(t,done=false){return `<div class="task-card ${t.priority==='urgent'?'urgent':''}"><div><span class="priority ${t.priority}">${esc(t.priority||'normal')}</span><b>${esc(t.title)}</b><small>📅 ${dateLabel(t.dueDate)} ${esc(t.dueTime||'')} · 👤 ${esc(t.responsible)}</small></div>${done?`<div class="row-actions"><span class="status-pill success">REALIZADA</span><button type="button" class="danger-link" data-delete-completed-task="${esc(t.id)}">Eliminar</button></div>`:`<button class="primary-button" data-complete-task="${t.id}">✓ Realizada</button>`}</div>`}

export function renderClose(content,period,branch="General"){
 if(branch==='General'){content.innerHTML=`<div class="page-intro"><div><span class="section-kicker">CIERRE CONSOLIDADO</span><h2>General es una vista de consulta</h2><p>El cierre mensual se realiza por sucursal.</p></div></div>${table(['Sucursal','Estado','Resultado'],CONFIG.branches.map(b=>{const s=Store.summary(period,b);return `<tr><td>${esc(b)}</td><td>${Store.periodStateLabel(period,b)}</td><td>${money(s.result)}</td></tr>`}).join(''))}`;return;}
 const s=Store.summary(period,branch),closed=Store.hasClosure(period,branch),versions=Store.db.closures.filter(x=>x.period===period&&x.branch===branch).sort((a,b)=>Number(b.version||0)-Number(a.version||0));
 const invoices=Store.list('invoices',period,branch),expenses=Store.list('expenses',period,branch),investments=Store.list('investments',period,branch),employees=Store.list('employees').filter(e=>e.active!==false&&e.branch===branch),hours=Store.list('hours',period,branch),liquidations=Store.list('liquidations',period,branch);
 const missingInvoice=invoices.filter(x=>!x.provider||!Number.isFinite(Number(x.amount))||!x.branch),late=invoices.filter(x=>String(x.loadDate||x.createdAt).slice(0,7)>period),missingExpense=expenses.filter(x=>!x.category||!Number.isFinite(Number(x.amount))||!x.branch),missingInvestment=investments.filter(x=>!x.concept||!Number.isFinite(Number(x.amount))||!x.branch),noHours=employees.filter(e=>!hours.some(h=>h.employeeId===e.id)),noLiquidation=employees.filter(e=>hours.some(h=>h.employeeId===e.id)&&!liquidations.some(l=>l.employeeId===e.id));
 const estimates=Store.list('estimates',period,branch),incomeEstimates=estimates.filter(x=>x.sector==='income'),salaryEstimates=estimates.filter(x=>x.sector==='salary'),realIncomeRows=Store.list('incomes',period,branch),incomeCovered=realIncomeRows.length>0||incomeEstimates.length>0,salaryEstimateCoversMissing=salaryEstimates.length>0;
 const checklist=[
  ['Ingresos',incomeCovered,`${realIncomeRows.length} reales · ${incomeEstimates.length} estimados · total considerado ${money(s.income)}${incomeCovered?'':' · agregá un valor estimado desde Inicio para cerrar sin rehacer Caja Diaria'}`,'dashboard'],
  ['Proveedores / facturas',true,`${s.invoiceCount} facturas · ${missingInvoice.length?missingInvoice.length+' requieren revisión':'sin datos obligatorios faltantes'}`,'invoices'],
  ['Gastos del local',missingExpense.length===0,`${s.expenseCount} gastos · ${missingExpense.length?missingExpense.length+' requieren revisión':'controlados'}`,'expenses'],
  ['Inversiones',missingInvestment.length===0,`${s.investmentCount} inversiones · ${missingInvestment.length?missingInvestment.length+' requieren revisión':'controladas'}`,'investments'],
  ['Horas',noHours.length===0||salaryEstimateCoversMissing,`${number(s.hours)} horas · ${noHours.length?(salaryEstimateCoversMissing?'Faltan horas; cubierto por estimación de Personal':noHours.length+' empleados sin carga; podés usar Agregar valor estimado'):'carga registrada'}`,'hours'],
  ['Liquidaciones',noLiquidation.length===0||salaryEstimateCoversMissing,`${s.liquidationCount} liquidaciones vigentes · ${noLiquidation.length?(salaryEstimateCoversMissing?'Pendientes cubiertas por estimación de Personal':noLiquidation.length+' empleados pendientes; podés usar Agregar valor estimado'):'sin pendientes'}`,'hours'],
  ['Facturas posteriores al período',true,late.length?`${late.length} factura(s) cargada(s) después del período`:'No se detectaron cargas posteriores','invoices'],
  ['Cierre formal del período',true,closed?'Ya existe un cierre vigente':'Listo para cerrar, incluso si el mes es histórico','close']
 ];
 const blockers=checklist.filter(x=>!x[1]);
 content.innerHTML=`<div class="profile-bar"><div><span class="section-kicker">CIERRE MENSUAL CONTROLADO</span><b>${esc(branch)}</b><small>Caja Diaria es independiente y no es requisito para cerrar el período.</small></div><div class="profile-chips">${branchFilter(branch)}</div></div><div class="close-status ${closed?'closed':(Store.periodStateLabel(period,branch)==='CIERRE PENDIENTE'?'pending':'open')}"><div><span>ESTADO</span><strong>${Store.periodStateLabel(period,branch)}</strong></div><div><span>VERSIÓN ACTUAL</span><strong>${versions[0]?.version||0}</strong></div><div><span>RESULTADO</span><strong>${money(s.result)}</strong></div><div><span>RESPONSABLE</span><strong>${esc(versions[0]?.responsible||'Sin cerrar')}</strong></div></div><section class="panel"><div class="panel-head"><div><span class="section-kicker">CENTRO DE CONTROL MENSUAL</span><h3>Estado del período</h3></div>${closed?'<button class="secondary-button" data-reopen-period="1">Reabrir con motivo</button>':'<button class="primary-button" data-close-period="1" '+(blockers.length?'disabled title="Hay controles bloqueantes pendientes"':'')+'>Cerrar y generar PDF</button>'}</div><div class="close-check-grid">${checklist.map(([name,ok,detail,target])=>`<div class="close-check ${ok?'ok':'block'}"><div class="check-icon">${ok?'✓':'!'}</div><div><b>${esc(name)}</b><span>${esc(detail)}</span></div>${ok?'<strong>OK</strong>':`<button type="button" class="secondary-button compact-button" data-close-review="${esc(target||'dashboard')}">Revisar</button>`}</div>`).join('')}</div>${blockers.length?`<div class="notice danger-box">Hay ${blockers.length} controles que requieren revisión antes de cerrar.</div>`:'<div class="notice success">✓ El control previo no encontró bloqueos.</div>'}</section><section class="panel"><div class="panel-head"><div><span class="section-kicker">FOTOGRAFÍA</span><h3>Totales del cierre</h3></div></div><div class="close-summary"><div><span>Ingresos reales</span><b>${money(s.incomeReal)}</b></div><div><span>Ingresos estimados</span><b>${money(s.incomeEstimated)}</b></div><div><span>Total ingresos</span><b>${money(s.income)}</b></div><div><span>Gastos del local</span><b>${money(s.localExpense)}</b></div><div><span>Proveedores</span><b>${money(s.providers)}</b></div><div><span>Inversiones</span><b>${money(s.investment)}</b></div><div><span>Personal real</span><b>${money(s.salaryReal)}</b></div><div><span>Personal estimado</span><b>${money(s.salaryEstimated)}</b></div><div><span>Total personal</span><b>${money(s.salary)}</b></div><div><span>Resultado</span><b>${money(s.result)}</b></div><div><span>Caja diaria</span><b>Separada</b></div></div></section><section class="panel"><div class="panel-head"><div><span class="section-kicker">VERSIONES DEL CIERRE</span><h3>Historial completo</h3></div></div>${versions.map(v=>`<div class="version-row"><div><b>Versión ${v.version}</b><span>${dateTimeLabel(v.closedAt)} · ${esc(v.responsible)} · ${esc(v.status)}</span></div><strong>${money(v.summary?.result)}</strong><button class="secondary-button" data-close-version="${v.id}">PDF</button></div>`).join('')||'<div class="empty-block">Todavía no hay cierres registrados.</div>'}</section>`;
}
export function renderFiles(content,period,branch="General"){
 const allFiles=Store.list('files').sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));
 const files=allFiles.filter(f=>branch==='General'||f.branch===branch);
 const groups=new Map();
 for(const f of files){const dt=String(f.period||period), year=dt.slice(0,4)||'Sin año', month=dt.slice(5,7)||'00', key=`${year}|${month}|${f.branch||'General'}|${f.sector||'Documento'}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(f);}
 const groupHtml=[...groups.entries()].map(([key,items])=>{const [year,month,b,se]=key.split('|');return `<details class="file-folder" open><summary><span>📁 ${esc(year)} / ${esc(periodLabel(`${year}-${month}`))} / ${esc(b)} / ${esc(se)}</span><b>${items.length}</b></summary><div class="file-grid">${items.map(f=>{const integrity=Store.fileIntegrity(f);return `<article class="file-card"><div class="file-type">📄 ${esc(f.mime||'PDF')}</div><h3>${esc(f.name)}</h3><p>${esc(f.sector||'Documento')} · ${esc(f.branch||'General')} · ${periodLabel(f.period||period)}</p><div class="file-meta"><span>Generado: ${dateTimeLabel(f.createdAt)}</span><span>Responsable: ${esc(f.responsible||'—')}</span><span>Versión: ${esc(f.version||1)}</span><span>Ruta: ${esc(f.storagePath||'local/archivos')}</span></div><div class="file-integrity ${integrity.status==='ok'?'ok':integrity.status==='anterior'?'warning':'neutral'}">${integrity.status==='ok'?'✓ Integridad vigente':integrity.status==='anterior'?'⚠ Documento anterior al último cambio':'• Sin comparación de origen'}</div><div class="row-actions"><button class="secondary-button" data-view-file="${esc(f.id)}">Ver</button><button class="primary-button" data-download-file="${esc(f.id)}">Descargar</button><button class="secondary-button" data-print-file="${esc(f.id)}">Imprimir</button><button type="button" class="danger-link" data-delete="files" data-id="${esc(f.id)}">Eliminar</button></div></article>`}).join('')}</div></details>`}).join('')||'<div class="empty-block">No hay documentos para este contexto.</div>';
 content.innerHTML=`<div class="page-intro"><div><span class="section-kicker">REPOSITORIO DOCUMENTAL</span><h2>Archivos</h2><p>Organizados por año, mes, sucursal y sector. Cada archivo conserva ficha documental, versión, ubicación e integridad.</p></div><button class="secondary-button" data-view-jump="import">Importar / backup</button></div><div class="file-filters"><span>${files.length} documentos visibles</span><span>${allFiles.length} documentos en el repositorio local</span><span>Perfil: ${esc(branch)} · ${periodLabel(period)}</span></div>${groupHtml}`;
}

export function auditForContext(contextPeriod,contextBranch){
 const rows=Store.db.audit||[];
 return rows.filter(x=>{
   if(contextBranch==='General') return x.period===contextPeriod || (!x.period && !x.branch);
   return x.period===contextPeriod && x.branch===contextBranch;
 });
}
export function renderHistory(content,period=window.__blunnoPeriod||today().slice(0,7),branch=window.__blunnoBranch||"General"){
 const data=auditForContext(period,branch);
 content.innerHTML=`<div class="page-intro"><div><span class="section-kicker">AUDITORÍA PERMANENTE</span><h2>Historial y trazabilidad</h2><p>Fecha, hora, minuto, responsable, sector, sucursal, período, acción, registro afectado y antes/después. La auditoría no se elimina.</p></div><button class="secondary-button" id="exportAudit">Exportar auditoría</button><button class="secondary-button" data-pdf-close="history">PDF</button></div>${table(['Fecha / hora','Acción','Sector','Sucursal','Período','Responsable','Registro','Cambios'],data.map(x=>`<tr><td>${dateTimeLabel(x.at)}</td><td><span class="audit-action">${esc(x.action)}</span></td><td>${esc(x.sector||x.collection)}</td><td>${esc(x.branch||'—')}</td><td>${x.period?esc(periodLabel(x.period)):'—'}</td><td>${esc(x.responsible||'—')}</td><td>${esc(x.collection)} · ${esc(x.recordId)}</td><td><details><summary>Ver</summary><pre class="audit-pre">${esc(JSON.stringify({antes:x.before,despues:x.after},null,2))}</pre></details></td></tr>`).join(''))}`;
}

export function renderTrash(content){
 const data=Store.trash().sort((a,b)=>String(b.deletedAt).localeCompare(String(a.deletedAt)));
 content.innerHTML=`<div class="page-intro"><div><span class="section-kicker">PAPELERA SEGURA</span><h2>Elementos eliminados</h2><p>Los registros permanecen 30 días. Podés seleccionar varios para restaurarlos o eliminarlos definitivamente. La eliminación definitiva también queda auditada.</p></div></div>
 <div class="trash-toolbar"><div><b>${data.length}</b><span> elementos en papelera</span></div><div><button class="secondary-button" id="trashRestoreSelected" ${data.length?'':'disabled'}>↶ Restaurar seleccionados</button><button class="danger-button" id="trashPurgeSelected" ${data.length?'':'disabled'}>Eliminar definitivamente</button><button class="danger-link" id="trashEmpty" ${data.length?'':'disabled'}>Vaciar papelera</button></div></div>
 ${table(['<input type="checkbox" id="trashSelectAll">','Sector','Registro','Eliminado','Responsable','Vence','Acciones'],data.map(x=>{const expires=new Date(new Date(x.deletedAt).getTime()+30*86400000);return `<tr><td><input type="checkbox" class="trash-select" data-collection="${esc(x._collection)}" data-id="${esc(x.id)}"></td><td>${esc(x._collection)}</td><td><b>${esc(x.name||x.concept||x.title||x.provider||x.id)}</b></td><td>${dateTimeLabel(x.deletedAt)}</td><td>${esc(x.responsible||'—')}</td><td>${dateTimeLabel(expires.toISOString())}</td><td><button class="secondary-button" data-restore="${esc(x._collection)}" data-id="${esc(x.id)}">Restaurar</button><button class="danger-link" data-purge="${esc(x._collection)}" data-id="${esc(x.id)}">Eliminar</button></td></tr>`}).join(''))}`;
}

export function renderImport(content){content.innerHTML=`<div class="page-intro"><div><span class="section-kicker">EXCEL / RESPALDOS</span><h2>Excel / Backup</h2><p>El Excel se analiza completo, hoja por hoja y de arriba hacia abajo. El sistema identifica el sector, conserva los datos y muestra cualquier fila que necesite revisión antes de guardar.</p></div></div><div class="import-grid"><section class="panel"><span class="section-kicker">IMPORTACIÓN COMPLETA</span><h3>Analizar todo el Excel</h3><p>Subí un Excel y BLUNNO revisará todas sus hojas y filas. Las filas válidas se agrupan automáticamente por sector; las ambiguas o incompletas quedan señaladas para no perder ni inventar información.</p><input id="excelInput" type="file" accept=".xlsx,.xls,.csv" class="file-input"><button class="primary-button" id="analyzeWorkbookButton" type="button">Analizar todo el Excel</button><div id="importPreview"></div></section><section class="panel"><span class="section-kicker">RESPALDOS</span><h3>Seguridad</h3><p>Generá una copia completa o restaurá un respaldo después de confirmarlo. Los documentos activos y los de Papelera también se incluyen cuando el binario es recuperable; el manifiesto indica si falta alguno.</p><div class="backup-actions"><button class="secondary-button" id="backupZipButton">Descargar backup completo ZIP</button><button class="secondary-button" id="backupButton">Descargar datos JSON</button><button class="secondary-button" id="exportExcelButton">Exportar Excel Blunno</button><label class="secondary-button file-button-label">Restaurar datos JSON<input id="backupRestoreInput" type="file" accept=".json,application/json" hidden></label></div></section></div><section class="panel"><span class="section-kicker">ESTADO DEL ALMACENAMIENTO</span><h3>Protección de registros</h3><p id="blunnoStorageHealth" role="status" aria-live="polite">Comprobando almacenamiento y sincronización...</p><p class="muted">Los datos de negocio y la auditoría se conservan. Exportá copias de seguridad periódicas; la copia local no reemplaza una copia externa.</p></section><section class="panel"><span class="section-kicker">CONTROL DE EXPORTACIÓN</span><h3>Archivos ordenados</h3><p>La exportación genera hojas separadas, columnas dimensionadas, encabezados congelados, filtros y formatos numéricos para evitar renglones o columnas cruzadas.</p><div class="page-actions"><button class="secondary-button" data-pdf-close="excel">Generar PDF</button><button class="secondary-button" data-print-view="excel">Imprimir</button></div></section>`} 
export function renderPeriodModal(){return Store.db.periods.slice().sort((a,b)=>String(b.id).localeCompare(String(a.id)));}
export function renderView(view,content,period,branch="General",compareA=prevPeriod(period),compareB=period){
 const map={dashboard:renderDashboard,income:renderIncome,cash:renderCash,providers:renderProviders,invoices:renderInvoices,expenses:renderExpenses,investments:renderInvestments,people:renderPeople,hours:renderHours,results:renderResults,compare:renderCompare,tasks:renderTasks,close:renderClose,files:renderFiles,history:renderHistory,trash:renderTrash,import:renderImport};
 if(view==="compare") return renderCompare(content,period,branch,compareA,compareB);
 (map[view]||renderDashboard)(content,period,branch);
}
